import{c as s,Q as a,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Claude Opus 4.8 System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-opus-4-8-system-card","title":"Claude Opus 4.8 System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2026-05-28T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-opus-4-8-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2026-05-28-claude-opus-4-8-system-card.md","filePath":"research/papers/2026-05-28-claude-opus-4-8-system-card.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-05-28-claude-opus-4-8-system-card.md"};function n(i,e,c,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="claude-opus-4-8-system-card" tabindex="-1">Claude Opus 4.8 System Card <a class="header-anchor" href="#claude-opus-4-8-system-card" aria-label="Permalink to &quot;Claude Opus 4.8 System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-opus-4-8-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-opus-4-8-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%20Opus%204.8%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: May 28, 2026</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。本卡為當前 workspace 主力模型（claude-opus-4-8）的官方文件。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Opus 4.8 為 Opus 4.7 的增量旗艦升級，核心敘事不在 coding 跳分，而在 <strong>honesty / alignment</strong>：更積極標記程式缺陷、降低 misalignment incidence，並引入更便宜的 fast mode。安全檔位延續 ASL-3。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Opus 4.8</strong>（API: claude-opus-4-8）：最新 GA 旗艦；coding 小幅進步，主打誠實度與對齊。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>88.6%</strong>（由 4.7 的 87.6% 提升，+1pp）。</li><li><strong>SWE-bench Pro</strong>：<strong>69.2%</strong>（領先同期 GPT-5.5 58.6%、Gemini 3.1 Pro 54.2%）。</li><li><strong>Honesty / 缺陷標記</strong>：較 Opus 4.7 約 <strong>4× 更不易</strong>讓 code flaw 漏標而不警示。</li><li><strong>Misalignment incidence</strong>：<strong>~1.9</strong>（4.7 為 ~2.5；官方稱「與 Mythos Preview 大致打平」）。</li><li><strong>Pricing</strong>：<strong>$5 / 1M input、$25 / 1M output</strong>（同 4.7）；fast mode 約 2.5× 速度、$10/$50，較 4.7 fast mode 便宜約 3×。</li><li><strong>AI Safety Level</strong>：<strong>ASL-3</strong>（同 4.7）。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li>誠實度為發布主軸而非 benchmark 跳分——「working ≠ honest」的對齊側深化。</li><li>misalignment incidence 已逼近受限的 Mythos Preview，顯示對齊投資的邊際成果。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong>ceiling 檔位的世代參照之一</strong>：本卡是 <code>pilot</code>（tier=ceiling，原 <code>opus-pilot</code>）在 Opus 4.8 世代的能力底座。⚠️ 原文寫「即當前 session 的 claude-opus-4-8」——該敘述已於 2026-08-02 失效（harness 已換代，<code>HARNESS_MODEL_VERSION</code> 見 session-init 輸出）。<strong>「當前 session 模型」這類隨 session 變動的事實不應寫入 corpus</strong>（<code>context-management.md</code> §Prompt Caching 禁令①：動態事實不寫穩定前綴）；模型檔位對照請一律以 <code>refs/model-profiles.md</code> 為 SSoT。</li><li><strong>誠實度 ↔ unverified_success / anti-hack</strong>：core.md「subagent 自報成功須親驗」「anti-hack 雙重驗證」——4.8 更積極標記缺陷，但 4x 改善仍非 100%，機械驗證閘門不可撤。</li><li><strong>fast mode 便宜化 ↔ effort-first / finops</strong>：fast mode 降價使「速度 vs 成本」trade-off 在 Opus 檔位更有彈性，呼應 effort-first 與成本紀律。</li><li><strong>misalignment ~1.9 ↔ The Loop RECORD</strong>：對齊非歸零，core.md「assisted-success ≠ autonomous-success」的人工介入歸因仍須保留。</li></ul>',17)])])}const m=s(r,[["render",n]]);export{h as __pageData,m as default};
